 Promise.resolve(document.modelContext.registerTool({name:'open_estateos_inspection',title:'Open inspection report',description:'Open an inspection already accessible to the signed-in account. Does not publish or modify records.',inputSchema:{type:'object',properties:{inspectionId:{type:'string'}},required:['inspectionId'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},async execute(input){if(!input||typeof input.inspectionId!=='string'||Object.keys(input).length!==1)throw Error('Provide an inspectionId.');await load();const report=data.inspections.find(i=>i.id===input.inspectionId);if(!report)throw Error('Inspection unavailable to this account.');activeInspection=report.id;page='inspection';render();return {id:report.id,status:report.status};}},{signal:lifecycle.signal})).catch(()=>{});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
