// Browser history tracks the in-app views without storing account content or secrets.
let navigationOwner=null, navigationRestoring=false;
function navigationView(){return {page,propertyId,tab,activeInspection,activeAssetInspection,assetInspectionReadOnly,activeArrival,arrivalFilter,inspectionUpcomingOnly,activeClient};}
function restoreNavigation(v){page=v.page||'dashboard';propertyId=v.propertyId||null;tab=v.tab||'overview';activeInspection=v.activeInspection||null;activeAssetInspection=v.activeAssetInspection||null;assetInspectionReadOnly=!!v.assetInspectionReadOnly;activeArrival=v.activeArrival||null;arrivalFilter=v.arrivalFilter||'pending';inspectionUpcomingOnly=!!v.inspectionUpcomingOnly;activeClient=v.activeClient||null;search='';}
function initializeNavigation(){if(navigationOwner===data.user.id)return;navigationOwner=data.user.id;const state=history.state;if(state?.estateos&&state.owner===navigationOwner)restoreNavigation(state.view);else{restoreNavigation({page:'dashboard'});history.replaceState({estateos:true,owner:navigationOwner,view:navigationView(),depth:0},'',location.pathname);}}
function recordNavigation(){if(navigationRestoring)return;const view=navigationView(),previous=history.state;if(previous?.estateos&&JSON.stringify(previous.view)===JSON.stringify(view))return;history.pushState({estateos:true,owner:navigationOwner,view,depth:(previous?.depth||0)+1},'',location.pathname+'#'+encodeURIComponent(page));window.scrollTo(0,0);}
window.addEventListener('popstate',event=>{if(!data)return;const state=event.state;if(!state?.estateos||state.owner!==data.user.id)return;$('modal')?.close();navigationRestoring=true;restoreNavigation(state.view);try{render();window.scrollTo(0,0);}finally{navigationRestoring=false;}});

