async function staffAction(name,key){
 if(name==='staff-profile'){
  const u=data.staff.people.find(u=>u.id===key)||{},d=data.staff.profiles.find(p=>p.user_id===key)?.details||{};
  return createForm(key?'Edit staff member':'Create staff member',input('name','Staff name','text',u.name||'')+input('email','Login email','email',u.email||'')+(!key?input('password','Initial password (at least 12 characters)','password'):'')+input('phone','Phone','tel',d.phone||'',false)+input('jobTitle','Job title','text',d.jobTitle||'',false)+input('employmentType','Employment type','text',d.employmentType||'',false)+input('address','Address','text',d.address||'',false)+input('startDate','Start date','date',d.startDate||'',false)+input('endDate','End date (optional)','date',d.endDate||'',false)+input('payRate','Pay rate','number',d.payRate??'',false).replace('type="number"','type="number" step="0.01" min="0"')+select('payBasis','Rate basis',['hour','day','week','year'].map(v=>`<option ${d.payBasis===v?'selected':''}>${v}</option>`).join(''))+input('currency','Currency code','text',d.currency||'USD')+input('emergencyName','Emergency contact name','text',d.emergencyName||'',false)+input('emergencyPhone','Emergency contact phone','tel',d.emergencyPhone||'',false)+textarea('notes','Employment notes',d.notes||''),'staff/profile',{userId:key||null});
 }
 if(name==='staff-schedule'){
  const s=data.staff.schedules.find(s=>s.id===key)||{};const local=v=>{if(!v)return '';const d=new Date(v);return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
  return dialog(key?'Edit schedule':'Create schedule',input('title','Shift or visit title','text',s.title||'')+select('staffId','Staff member',option(data.staff.people.filter(u=>u.active),'id','name',s.user_id))+select('propertyId','Residence (optional)','<option value="">No specific residence</option>'+option(data.properties,'id','name',s.property_id))+input('startsAt','Starts (local time)','datetime-local',local(s.starts_at))+input('endsAt','Ends (local time)','datetime-local',local(s.ends_at))+textarea('notes','Schedule notes',s.notes||''),'Save',async b=>{await api('staff/schedule',{...b,id:key||null,startsAt:new Date(b.startsAt).toISOString(),endsAt:new Date(b.endsAt).toISOString()});});
 }
 if(name==='schedule-remove'){if(confirm('Remove this schedule? Work orders and staff assignments will be kept.')){await api('staff/schedule/remove',{id:key});await load();}return;}
 if(name==='work-assignment'){const w=data.work.find(w=>w.id===key),a=data.staff.assignments.find(a=>a.work_id===key)||{};return createForm('Assign work / add to schedule',staffAssignmentFields(a)+select('vendorId','Assigned vendor (choose staff OR vendor)','<option value="">No vendor assigned</option>'+option(data.vendors,'id','name',w.vendor_id)),'staff/assign',{workId:key});}
 if(name==='schedule-work')return scheduleTaskForm(key);
}
function scheduleTaskForm(key){
 const s=data.staff.schedules.find(s=>s.id===key);
 dialog('Assign work',select('kind','Work type','<option value="work">Work order</option><option value="inspection">Residence inspection</option><option value="arrival">Arrival preparation</option><option value="asset">Asset inspection</option><option value="other">Other</option>')+'<div id="schedule-task-fields" class="field full"></div>','Assign',async b=>{
  if(b.kind==='work')await api('staff/assign',{workId:b.workId,staffId:s.user_id,scheduleId:s.id});
  else await api('staff/task',{...b,scheduleId:s.id});
 });
 const draw=()=>{const kind=$('f-kind').value,slot=$('schedule-task-fields');
  if(kind==='work'){slot.innerHTML=select('workId','Existing work order','<option value="">Choose work order</option>'+option(data.work.filter(w=>!['completed','cancelled'].includes(w.status)&&(!s.property_id||s.property_id===w.property_id)),'id','title'));return;}
  slot.innerHTML=select('propertyId','Residence',option(data.properties.filter(p=>!s.property_id||p.id===s.property_id)))+'<div id="schedule-task-reference"></div>'+(kind==='other'?input('title','Task title'):'')+textarea('instructions',kind==='other'?'What needs to be done':'Instructions (optional)');
  const refs=()=>{const pid=$('f-propertyId').value,target=$('schedule-task-reference');target.innerHTML=kind==='asset'?select('referenceId','Asset','<option value="">Choose asset</option>'+option(data.assets.filter(a=>a.property_id===pid))):kind==='arrival'?select('referenceId','Arrival','<option value="">Choose arrival</option>'+data.arrivals.filter(a=>a.property_id===pid).map(a=>`<option value="${esc(a.id)}">${esc(new Date(a.arrival_at).toLocaleString())} · ${esc(label(a.status))}</option>`).join('')):'';};
  $('f-propertyId').onchange=refs;refs();
 };$('f-kind').onchange=draw;draw();
}
function sidebarStorageKey(){return 'residence-sidebar-groups:'+data.user.id;}
function groupedNavigation(nav){
 const groups=[['residences','Residences & Clients',['properties','clients','arrivals','shopping']],['operations','Daily Operations',['work','requests','inspections','calendar','routes','approvals']],['people','Staff & Vendors',['staff','staff-schedules','vendors','users']],['records','Property Records',['assets','maintenance','documents']],['administration','Administration',['platform','workspace','billing','audit','automation','email-activity']]];
 let saved={};try{saved=JSON.parse(localStorage.getItem(sidebarStorageKey())||'{}')||{};}catch{}
 const active=({property:'properties',inspection:'inspections','asset-inspection':'assets'})[page]||page;
 const item=([id,title])=>`<button data-action="navigate" data-id="${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${esc(title)}${id==='notifications'&&data.notifications.some(n=>!n.read_at)?' •':''}</button>`;
 return `<nav aria-label="Main navigation" class="grouped-nav">${nav.filter(n=>['dashboard','messages'].includes(n[0])).map(item).join('')}${groups.map(([id,title,ids])=>{const entries=ids.map(key=>nav.find(n=>n[0]===key)).filter(Boolean);if(!entries.length)return '';const open=entries.some(n=>n[0]===active)||saved[id]===true;return `<details class="nav-group" data-nav-group="${id}" ${open?'open':''}><summary>${esc(title)}<span class="nav-chevron" aria-hidden="true">›</span></summary><div class="nav-group-items">${entries.map(item).join('')}</div></details>`;}).join('')}</nav><nav class="account-nav" aria-label="Your account">${nav.filter(n=>['profile','notifications'].includes(n[0])).map(item).join('')}</nav>`;
}
document.addEventListener('toggle',event=>{const el=event.target;if(!el.matches?.('details[data-nav-group]')||!el.isConnected||!data?.user)return;try{const key=sidebarStorageKey();const saved=JSON.parse(localStorage.getItem(key)||'{}')||{};saved[el.dataset.navGroup]=el.open;localStorage.setItem(key,JSON.stringify(saved));}catch{}},true);

function requestPriorityField(value="Normal"){return select("priority","Priority",["Low","Normal","High","Urgent"].map(p=>`<option ${p===value?"selected":""}>${p}</option>`).join(""));}
function requestPriorityBadge(value="Normal"){return `<span class="badge ${value==="Urgent"?"red":value==="High"?"amber":""}">${esc(value)} priority</span>`;}
function dashboardTileGroups(){
 const tile=([title,num,target])=>`<button class="stat stat-link" data-action="navigate" data-id="${target}" type="button"><div class="eyebrow">${esc(title)}</div><b>${num}</b><span class="muted">View details →</span></button>`;
 const residences=[['Residences',data.properties.length,'properties'],['Upcoming arrivals',data.arrivals.filter(a=>!['completed','cancelled'].includes(a.status)).length,'arrivals'],['Submitted arrivals',data.arrivals.filter(a=>['submitted','preparing'].includes(a.status)).length,'arrivals']];
 const operations=[['Inspection reports',data.inspections.filter(i=>i.status==='published').length,'inspections'],['Upcoming inspections',upcomingInspections().length,'inspections-upcoming'],['Work orders',data.work.filter(w=>!['completed','cancelled'].includes(w.status)).length,'work'],['Service requests',data.requests.filter(r=>r.status!=='completed').length,'requests']];
 if(data.user.role==='vendor')return `<section class="dashboard-group"><h2>Assigned work</h2><div class="stats">${operations.filter(t=>t[2]==='work').map(tile).join('')}</div></section>`;
 return `<section class="dashboard-group" aria-labelledby="residence-arrivals-title"><h2 id="residence-arrivals-title">Residences & Arrivals</h2><div class="stats dashboard-residences">${residences.map(tile).join('')}</div></section><section class="dashboard-group" aria-labelledby="inspection-service-title"><h2 id="inspection-service-title">Inspections & Service</h2><div class="stats dashboard-operations">${operations.map(tile).join('')}</div></section>`;
}

function invitationEmailMessage(status){return status==='sent'?'Invitation submitted for email delivery.':status==='not_configured'?'Email sending is not configured. Copy and share this invitation link.':'Email could not be sent. Copy and share this invitation link.';} 

function invitationHistoryView(){
 const invitations=data.invitations||[];
 const counts=status=>invitations.filter(i=>i.status===status).length;
 const when=value=>new Date(value).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});
 return `<div class="panel table-wrap"><h3>Invitations</h3><p class="muted">${counts('pending')} pending · ${counts('accepted')} accepted · ${counts('expired')} expired · ${counts('cancelled')} cancelled</p><p class="muted">Track account acceptance here. Pending does not confirm email delivery.</p>${invitations.length?`<table><thead><tr><th>Recipient</th><th>Role</th><th>Status</th><th>Expires</th><th>Accepted</th><th>Actions</th></tr></thead><tbody>${invitations.map(i=>`<tr><td>${esc(i.email)}</td><td>${esc(label(i.role))}</td><td>${badge(i.status)}</td><td>${i.expiresAt?esc(when(i.expiresAt)):'—'}</td><td>${i.acceptedAt?esc(when(i.acceptedAt)):'—'}</td><td>${i.status==='pending'?`<div class="actions">${btn('Edit email','edit-invite-email',i.id)}${btn('Cancel invitation','cancel-invite',i.id)}</div>`:'—'}</td></tr>`).join('')}</tbody></table>`:empty('No invitations yet. Use Invite someone to get started.')}</div>`;
}

function familyMemberActions(p,m){
 if(data.user.role!=='admin')return '';
 const email=String(m.email||'').trim().toLowerCase();
 const account=data.users.find(u=>u.role==='client'&&u.client_id===p.client_id&&((m.accessUserIds||[]).includes(u.id)||(email&&u.email.toLowerCase()===email)));
 const pending=(data.invitations||[]).filter(i=>i.clientId===p.client_id&&i.role==='client'&&i.status==='pending'&&((m.invitationIds||[]).includes(i.id)||(email&&i.email.toLowerCase()===email)));
 const action=(text,name)=>`<button data-action="${name}" data-id="${esc(m.id)}" data-property-id="${esc(p.id)}">${text}</button>`;
 return `<div><div class="muted">${account?(account.active?'Client access active':'Client access suspended'):pending.length?'Invitation pending':email?'Not invited':'Add an email to invite'}</div><div class="actions">${action(email?'Edit email':'Add email','family-member-email')}${!account&&!pending.length&&email?action('Send invite','family-send-invite'):''}${pending.map(i=>btn('Cancel invitation','cancel-invite',i.id)).join('')}${action('Remove','residence-member-delete')}</div></div>`;
}

function inspectionEmailMessage(status){return ({sent:'PDF submitted for email delivery.',sending:'Email is being processed. Check again shortly.',failed:'Email could not be sent. Retry sending the report.',not_configured:'Email sending is not configured. The PDF is still available to download.',too_large:'This PDF is too large to email. Download it to share separately.',not_requested:'No email recipient was saved.'})[status]||'No email has been sent.';}

function inspectionRecipient(p){if(!p)return '';return '<div class="notice inspection-due"><div><strong>Inspection report email</strong><p>'+esc(p.inspection_report_email||'No email saved')+'</p><span class="muted">Completed reports are automatically sent to this saved address.</span></div>'+ (data.user.role==='admin'?btn(p.inspection_report_email?'Edit report email':'Set report email','inspection-recipient',p.id):'')+'</div>'; }

let activeMessageThread=null,messageDetail=null;
function companyLogo(){return data.companyLogo?'<img class="company-logo" src="'+esc(data.companyLogo)+'" alt="'+esc(data.company)+' logo">':'';}
function logoField(editing=false){return '<div class="field full"><label for="company-logo">Company logo (optional)</label><input type="file" id="company-logo" name="companyLogo" accept="image/png,image/jpeg"><p class="muted">PNG or JPEG, up to 5 MB. Your logo appears beside Powered by EstateAegis and on inspection reports. Transparent backgrounds are preserved.</p>'+'<label class="logo-background-option"><input type="checkbox" name="removeBackground" checked> Remove a plain background automatically</label><p class="muted">Best for solid backgrounds around a logo. Uncheck to keep the original background. Saving also processes your current logo.</p>'+(editing&&data.companyLogo?companyLogo()+'<label><input type="checkbox" name="removeLogo"> Remove current logo</label>':'')+'</div>';}
async function readCompanyLogo(form){let file=form.querySelector('[name=companyLogo]')?.files?.[0];if(!file&&form.querySelector('[name=removeLogo]')?.checked)return '';if(!file){const existing=typeof data!=='undefined'&&data?.companyLogo;if(!existing)return undefined;const [prefix,encoded]=existing.split(',');file=new Blob([Uint8Array.from(atob(encoded),c=>c.charCodeAt(0))],{type:prefix.includes('image/png')?'image/png':'image/jpeg'});}if(!['image/png','image/jpeg'].includes(file.type)||file.size>5*1024*1024)throw Error('Choose a PNG or JPEG logo under 5 MB.');const image=await createImageBitmap(file);try{if(image.width*image.height>40000000)throw Error('Choose a smaller logo image.');const scale=Math.min(1,1000/image.width,500/image.height),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const context=canvas.getContext('2d');context.drawImage(image,0,0,canvas.width,canvas.height);if(form.querySelector('[name=removeBackground]')?.checked){const pixels=context.getImageData(0,0,canvas.width,canvas.height);context.putImageData(removeLogoBackground(pixels),0,0);}return canvas.toDataURL('image/png');}finally{image.close();}}
function messagesView(){const threads=data.messaging.threads;const current=threads.find(t=>t.id===activeMessageThread);if(current&&messageDetail?.thread.id===current.id)return head(current.subject,current.kind==='announcement'?'Company-wide conversation · Replies go to all participants':'Direct conversation',btn('Back to messages','message-back'))+'<div class="panel"><p class="muted">'+esc(current.people.map(u=>u.name).join(', '))+'</p><div class="actions">'+btn('Refresh','message-refresh')+(messageDetail.hasOlder?btn('Load older messages','message-older'):'')+'</div><div class="message-list">'+messageDetail.messages.map(m=>'<article class="message-bubble '+(m.sender_id===data.user.id?'message-own':'')+'"><div class="message-meta"><strong>'+esc(m.sender_name)+'</strong><time>'+esc(new Date(m.created_at).toLocaleString())+'</time></div><p class="pre">'+esc(m.body)+'</p></article>').join('')+'</div>'+btn('Reply','message-reply','',true)+'</div>';return head('Messages','Conversations with people in your company workspace.',btn('New message','message-new','',true))+ '<div class="panel"><div class="actions">'+btn('Refresh inbox','message-refresh')+'</div>'+ (threads.map(t=>'<div class="row"><div><strong>'+esc(t.subject)+'</strong><p class="muted">'+esc(t.kind==='announcement'?'Everyone in this company':t.people.filter(u=>u.id!==data.user.id).map(u=>u.name).join(', '))+' · '+esc(new Date(t.updated_at).toLocaleString())+'</p>'+(Number(t.unread)?'<span class="badge">'+Number(t.unread)+' unread</span>':'')+'</div>'+btn('Open conversation','message-open',t.id)+'</div>').join('')||empty('No messages yet. Start a conversation with someone in your company.'))+'</div>';}

let workspaceNameObserver;
function fitWorkspaceName(){workspaceNameObserver?.disconnect();const el=document.querySelector(".workspace-brand strong");if(!el)return;const fit=()=>{el.style.fontSize="24px";const width=el.clientWidth;if(width&&el.scrollWidth>width)el.style.fontSize=(24*width/el.scrollWidth)+"px";};fit();workspaceNameObserver=new ResizeObserver(fit);workspaceNameObserver.observe(el.parentElement);document.fonts.ready.then(()=>{if(el.isConnected)fit();});}
